-- A lending library's legacy schema: integer keys of every width, a
-- composite key, validated and unvalidated foreign keys, and a uuid key.

CREATE SCHEMA IF NOT EXISTS library;

CREATE TABLE library.branches (
    id smallint PRIMARY KEY,
    name text NOT NULL
);

CREATE TABLE library.members (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    home_branch_id smallint NOT NULL REFERENCES library.branches (id),
    referrer_id integer,
    email text NOT NULL
);

CREATE TABLE library.copies (
    branch_id smallint NOT NULL REFERENCES library.branches (id),
    copy_no bigint NOT NULL,
    title text NOT NULL,
    PRIMARY KEY (branch_id, copy_no)
);

CREATE TABLE library.loans (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    member_id integer NOT NULL REFERENCES library.members (id),
    branch_id smallint NOT NULL,
    copy_no bigint NOT NULL,
    due_on date,
    FOREIGN KEY (branch_id, copy_no) REFERENCES library.copies (branch_id, copy_no)
);

ALTER TABLE library.members
    ADD CONSTRAINT members_referrer_id_fkey FOREIGN KEY (referrer_id)
    REFERENCES library.members (id) NOT VALID;

CREATE TABLE library.cards (
    id uuid PRIMARY KEY,
    member_id integer NOT NULL REFERENCES library.members (id)
);
